@Configuration
@EnableWebSecurity
public class SecurityConfig {

    @Bean
    public SecurityFilterChain securityFilterChain(HttpSecurity http) throws Exception {
        http
            .authorizeHttpRequests(auth -> auth
                .requestMatchers("/public/**").permitAll()
                .anyRequest().authenticated()
            )
            .addFilterBefore(new JwtAuthenticationFilter(), 
                             UsernamePasswordAuthenticationFilter.class);
        return http.build();
    }
}

// Reading the current authenticated user from anywhere
Authentication auth = SecurityContextHolder.getContext().getAuthentication();
String username = auth.getName();
boolean isAdmin = auth.getAuthorities().stream()
    .anyMatch(a -> a.getAuthority().equals("ROLE_ADMIN"));

// Authentication object structure
public interface Authentication extends Principal, Serializable {
    Collection<? extends GrantedAuthority> getAuthorities();
    Object getCredentials();   // password (cleared after auth)
    Object getPrincipal();     // UserDetails or username string
    boolean isAuthenticated();
}

// Setting authentication manually (e.g., in JWT filter)
UsernamePasswordAuthenticationToken authToken =
    new UsernamePasswordAuthenticationToken(
        userDetails,    // principal
        null,           // credentials (null for JWT — already verified)
        userDetails.getAuthorities()
    );
authToken.setDetails(
    new WebAuthenticationDetailsSource().buildDetails(request)
);
SecurityContextHolder.getContext().setAuthentication(authToken);

// Clearing context after request (done automatically by filter chain)
SecurityContextHolder.clearContext();

// What Spring Boot auto-configures (conceptually):
// - Form login at /login
// - HTTP Basic auth header support
// - CSRF token filter
// - All URLs require authentication
// - Random password printed to console

// Minimal override for a REST API:
@Bean
public SecurityFilterChain filterChain(HttpSecurity http) throws Exception {
    http
        .csrf(csrf -> csrf.disable())                     // Stateless REST
        .sessionManagement(s -> s
            .sessionCreationPolicy(SessionCreationPolicy.STATELESS))
        .formLogin(form -> form.disable())               // No HTML login
        .httpBasic(basic -> basic.disable());            // No Basic auth
    return http.build();
}

@Bean
public AuthenticationManager authManager(HttpSecurity http) throws Exception {
    AuthenticationManagerBuilder builder =
        http.getSharedObject(AuthenticationManagerBuilder.class);
    builder.authenticationProvider(daoAuthProvider());
    return builder.build();
}

@Bean
public DaoAuthenticationProvider daoAuthProvider() {
    DaoAuthenticationProvider provider = new DaoAuthenticationProvider();
    provider.setUserDetailsService(userDetailsService);
    provider.setPasswordEncoder(passwordEncoder());
    return provider;
}

@Service
public class CustomUserDetailsService implements UserDetailsService {

    @Autowired
    private UserRepository userRepository;

    @Override
    public UserDetails loadUserByUsername(String username)
            throws UsernameNotFoundException {
        User user = userRepository.findByUsername(username)
            .orElseThrow(() -> 
                new UsernameNotFoundException("User not found: " + username));

        List<GrantedAuthority> authorities = user.getRoles().stream()
            .map(role -> new SimpleGrantedAuthority(role.getName()))
            .collect(Collectors.toList());

        return new org.springframework.security.core.userdetails.User(
            user.getUsername(),
            user.getPassword(),   // must be BCrypt-encoded
            user.isEnabled(),
            true, true, true,     // account/credentials not expired, not locked
            authorities
        );
    }
}

@Bean
public PasswordEncoder passwordEncoder() {
    return new BCryptPasswordEncoder(12); // cost factor 12
}

