@Configuration
@EnableMethodSecurity  // replaces deprecated @EnableGlobalMethodSecurity
public class MethodSecurityConfig { }

@Service
public class OrderService {

    @PreAuthorize("hasRole('ADMIN')")
    public List<Order> getAllOrders() { ... }

    @PreAuthorize("hasRole('USER') and #userId == authentication.principal.id")
    public Order getOrder(Long userId, Long orderId) { ... }

    @PostAuthorize("returnObject.owner == authentication.name")
    public Document getDocument(Long id) { ... }

    @Secured("ROLE_ADMIN")  // older style, role only
    public void deleteUser(Long id) { ... }

    @RolesAllowed({"ROLE_ADMIN", "ROLE_MANAGER"})  // JSR-250 style
    public Report generateReport() { ... }
}

// Built-in SpEL expressions
@PreAuthorize("isAuthenticated()")
public Profile getProfile() { ... }

@PreAuthorize("hasRole('ADMIN') or hasAuthority('WRITE_POSTS')")
public Post createPost(Post post) { ... }

// Parameter binding — user can only update their own profile
@PreAuthorize("#userId == authentication.principal.id")
public void updateProfile(Long userId, ProfileDto dto) { ... }

// Custom security bean
@Component("orderSecurity")
public class OrderSecurityService {
    public boolean isOwner(Authentication auth, Long orderId) {
        return orderRepository.findById(orderId)
            .map(o -> o.getOwnerUsername().equals(auth.getName()))
            .orElse(false);
    }
}

@PreAuthorize("@orderSecurity.isOwner(authentication, #orderId)")
public Order getOrder(Long orderId) { ... }

@Component
public class CustomAuthEntryPoint implements AuthenticationEntryPoint {
    @Override
    public void commence(HttpServletRequest req, HttpServletResponse res,
            AuthenticationException ex) throws IOException {
        res.setStatus(HttpServletResponse.SC_UNAUTHORIZED); // 401
        res.setContentType(MediaType.APPLICATION_JSON_VALUE);
        res.getWriter().write(
            "{\"error\": \"Unauthorized\", \"message\": \"" + ex.getMessage() + "\"}");
    }
}

@Component
public class CustomAccessDeniedHandler implements AccessDeniedHandler {
    @Override
    public void handle(HttpServletRequest req, HttpServletResponse res,
            AccessDeniedException ex) throws IOException {
        res.setStatus(HttpServletResponse.SC_FORBIDDEN); // 403
        res.setContentType(MediaType.APPLICATION_JSON_VALUE);
        res.getWriter().write(
            "{\"error\": \"Forbidden\", \"message\": \"Insufficient permissions\"}");
    }
}

// Register in SecurityFilterChain:
http.exceptionHandling(e -> e
    .authenticationEntryPoint(customAuthEntryPoint)
    .accessDeniedHandler(customAccessDeniedHandler)
);

// JWT parts example (decoded):
// Header:
// { "alg": "HS256", "typ": "JWT" }

// Payload:
// {
//   "sub": "user123",
//   "iat": 1716000000,
//   "exp": 1716003600,   // 1 hour later
//   "roles": ["ROLE_USER", "ROLE_ADMIN"]
// }

// Building a JWT with jjwt:
String token = Jwts.builder()
    .subject(username)
    .issuedAt(new Date())
    .expiration(new Date(System.currentTimeMillis() + 3_600_000L))
    .claim("roles", roles)
    .signWith(getSigningKey())  // HMAC-SHA256
    .compact();
// Result: eyJhbGciOiJIUzI1NiJ9.eyJzdWIiOiJ1c2VyMTIzIi4uLn0.SIGNATURE

@Component
public class JwtUtil {

    @Value("${jwt.secret}")
    private String secretKey; // Base64-encoded 256-bit key

    private SecretKey getSigningKey() {
        byte[] keyBytes = Decoders.BASE64.decode(secretKey);
        return Keys.hmacShaKeyFor(keyBytes);
    }

    public Claims extractAllClaims(String token) {
        return Jwts.parser()
            .verifyWith(getSigningKey())
            .build()
            .parseSignedClaims(token)
            .getPayload();
        // Throws: ExpiredJwtException, SignatureException, MalformedJwtException
    }

    public String extractUsername(String token) {
        return extractAllClaims(token).getSubject();
    }

    public boolean validateToken(String token) {
        try {
            extractAllClaims(token); // throws if invalid
            return true;
        } catch (JwtException | IllegalArgumentException e) {
            return false;
        }
    }
}

@Component
public class JwtAuthenticationFilter extends OncePerRequestFilter {

    @Autowired private JwtUtil jwtUtil;
    @Autowired private UserDetailsService userDetailsService;

    @Override
    protected void doFilterInternal(HttpServletRequest request,
            HttpServletResponse response, FilterChain filterChain)
            throws ServletException, IOException {

        final String authHeader = request.getHeader("Authorization");

        if (authHeader == null || !authHeader.startsWith("Bearer ")) {
            filterChain.doFilter(request, response);
            return;  // no token — continue chain unauthenticated
        }

        String token = authHeader.substring(7);

        // Only process if not already authenticated
        if (SecurityContextHolder.getContext().getAuthentication() == null) {
            try {
                String username = jwtUtil.extractUsername(token);
                UserDetails userDetails =
                    userDetailsService.loadUserByUsername(username);

                if (jwtUtil.validateToken(token)) {
                    var authToken = new UsernamePasswordAuthenticationToken(
                        userDetails, null, userDetails.getAuthorities());
                    authToken.setDetails(
                        new WebAuthenticationDetailsSource().buildDetails(request));
                    SecurityContextHolder.getContext().setAuthentication(authToken);
                }
            } catch (JwtException e) {
                // Invalid token — context remains unauthenticated → 401
            }
        }
        filterChain.doFilter(request, response);
    }
}

@Service
public class RefreshTokenService {

    @Autowired private RefreshTokenRepository tokenRepo;
    @Autowired private JwtUtil jwtUtil;

    public RefreshToken createRefreshToken(String username) {
        RefreshToken token = RefreshToken.builder()
            .username(username)
            .token(UUID.randomUUID().toString())  // opaque random token
            .expiresAt(Instant.now().plus(7, ChronoUnit.DAYS))
            .build();
        return tokenRepo.save(token);
    }

    public String rotateAndRefresh(String refreshTokenValue) {
        RefreshToken stored = tokenRepo.findByToken(refreshTokenValue)
            .orElseThrow(() -> new InvalidTokenException("Invalid refresh token"));

        if (stored.getExpiresAt().isBefore(Instant.now()))
            throw new InvalidTokenException("Refresh token expired");

        tokenRepo.delete(stored);  // revoke old refresh token (rotation)
        createRefreshToken(stored.getUsername()); // issue new refresh token
        return jwtUtil.generateToken(stored.getUsername()); // new access token
    }
}

// For stateless REST APIs — disable CSRF:
http.csrf(csrf -> csrf.disable());

// For server-rendered apps — keep CSRF enabled (default):
// Spring auto-adds CsrfFilter with session-backed token store.
// In Thymeleaf: <input type="hidden" th:name="${_csrf.parameterName}" th:value="${_csrf.token}"/>

// Hybrid: disable CSRF only for API paths:
http.csrf(csrf -> csrf
    .ignoringRequestMatchers("/api/**")  // stateless API
    // CSRF stays active for /web/** (server-rendered forms)
);

@Bean
public CorsConfigurationSource corsConfigurationSource() {
    CorsConfiguration config = new CorsConfiguration();
    config.setAllowedOrigins(List.of("http://localhost:3000",
                                     "https://myapp.com"));
    config.setAllowedMethods(List.of("GET","POST","PUT","DELETE","OPTIONS"));
    config.setAllowedHeaders(List.of("Authorization", "Content-Type"));
    config.setAllowCredentials(true);
    config.setMaxAge(3600L);  // cache preflight for 1 hour

    UrlBasedCorsConfigurationSource source =
        new UrlBasedCorsConfigurationSource();
    source.registerCorsConfiguration("/**", config);
    return source;
}

// Reference in SecurityFilterChain:
http.cors(cors -> cors.configurationSource(corsConfigurationSource()));

// Stateless (for JWT REST APIs):
http.sessionManagement(session -> session
    .sessionCreationPolicy(SessionCreationPolicy.STATELESS));

// For session-based web apps — add concurrency control:
http.sessionManagement(session -> session
    .sessionCreationPolicy(SessionCreationPolicy.IF_REQUIRED)
    .maximumSessions(1)              // only 1 active session per user
    .maxSessionsPreventsLogin(false) // new login expels old session
    .expiredUrl("/login?expired")
);

@Bean
public SecurityFilterChain securityFilterChain(HttpSecurity http) throws Exception {
    http
        .authorizeHttpRequests(auth -> auth.anyRequest().authenticated())
        .oauth2ResourceServer(oauth2 -> oauth2
            .jwt(jwt -> jwt.jwtAuthenticationConverter(jwtConverter()))
        );
    return http.build();
}

// JwtDecoder — auto-configured if spring.security.oauth2.resourceserver.jwt.issuer-uri is set
// Or configure manually:
@Bean
public JwtDecoder jwtDecoder() {
    return NimbusJwtDecoder
        .withSecretKey(Keys.hmacShaKeyFor(secretBytes))
        .build();
}

// Custom role extraction from Keycloak-style claims:
@Bean
public JwtAuthenticationConverter jwtConverter() {
    JwtGrantedAuthoritiesConverter grantedConverter =
        new JwtGrantedAuthoritiesConverter();
    grantedConverter.setAuthoritiesClaimName("roles");
    grantedConverter.setAuthorityPrefix("ROLE_");
    JwtAuthenticationConverter converter = new JwtAuthenticationConverter();
    converter.setJwtGrantedAuthoritiesConverter(grantedConverter);
    return converter;
}
